BEGIN;
SET LOCAL request.jwt.claims='{"role":"service_role"}';
CREATE FUNCTION pg_temp.ph_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Prize handover: %',label;END IF;END$$;
DO $$
DECLARE c uuid:=gen_random_uuid();other_c uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();u uuid:=gen_random_uuid();actor uuid;leader uuid:=gen_random_uuid();hof uuid:=gen_random_uuid();spin uuid:=gen_random_uuid();automatic uuid:=gen_random_uuid();stamp timestamptz;old_notice uuid;current_notice uuid;r jsonb;n integer;
BEGIN
 INSERT INTO campuses(id,name,slug) VALUES(c,'[AUDIT rollback] Handover','audit-handover-'||c),(other_c,'[AUDIT rollback] Other','audit-handover-'||other_c);
 FOREACH actor IN ARRAY ARRAY[a,b,u] LOOP
  INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(actor,'audit-handover-'||actor||'@example.invalid','{"full_name":"[AUDIT rollback] Handover"}');
  UPDATE profiles SET campus_id=c,role='student',push_enabled=true WHERE id=actor;
 END LOOP;
 UPDATE profiles SET role='admin' WHERE id=a;UPDATE profiles SET role='admin',campus_id=other_c WHERE id=b;
 INSERT INTO notification_preferences(user_id,hp_updates,push_enabled) VALUES(u,true,true) ON CONFLICT(user_id) DO UPDATE SET hp_updates=true,push_enabled=true;
 INSERT INTO leaderboard_reward_fulfillments(id,user_id,rank,month,campus_id) VALUES(leader,u,1,to_char(now() AT TIME ZONE 'Africa/Lagos','YYYY-MM'),c);
 INSERT INTO hall_of_fame_rewards(id,user_id,campus_id) VALUES(hof,u,c);
 INSERT INTO exclusive_spin_fulfillments(id,user_id,prize_name,campus_id,result_snapshot) VALUES(spin,u,'Frozen physical prize',c,'{"prize_type":"physical"}'),(automatic,u,'Automatic HP',c,'{"prize_type":"hp"}');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a)::text,true);PERFORM set_config('role','authenticated',true);
 UPDATE leaderboard_reward_fulfillments SET status='fulfilled',fulfilled_by=a,fulfilled_at=now() WHERE id=leader;
 GET DIAGNOSTICS n=ROW_COUNT;PERFORM pg_temp.ph_assert(n=1,'native scoped update allowed');
 PERFORM set_config('role','none',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 SELECT fulfilled_at INTO stamp FROM leaderboard_reward_fulfillments WHERE id=leader;
 PERFORM pg_temp.ph_assert((SELECT count(*)=2 FROM notifications WHERE user_id=u AND reference_id=leader),'inbox/push captured in same handover');
 PERFORM pg_temp.ph_assert((SELECT count(*)=1 FROM notification_deliveries WHERE user_id=u AND notification_id IN (SELECT id FROM notifications WHERE reference_id=leader)),'durable dispatch survives Python interruption');
 PERFORM pg_temp.ph_assert((SELECT count(*)=1 FROM admin_audit_logs WHERE entity_id=leader::text),'audit committed with status');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a)::text,true);PERFORM set_config('role','authenticated',true);
 UPDATE leaderboard_reward_fulfillments SET status='fulfilled',fulfilled_by=b,fulfilled_at=now()+interval '1 day' WHERE id=leader;
 UPDATE leaderboard_reward_fulfillments SET status='fulfilled',notes='Collection receipt retained',fulfilled_by=b,fulfilled_at=now()+interval '1 day' WHERE id=leader;
 BEGIN UPDATE leaderboard_reward_fulfillments SET status='pending' WHERE id=leader;RAISE EXCEPTION 'missing terminal guard';EXCEPTION WHEN check_violation THEN NULL;END;
 UPDATE hall_of_fame_rewards SET status='box_prepared' WHERE id=hof;
 PERFORM set_config('role','none',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM pg_temp.ph_assert((SELECT fulfilled_at=stamp AND fulfilled_by=a FROM leaderboard_reward_fulfillments WHERE id=leader),'notes/retry cannot rewrite completed handover');
 PERFORM pg_temp.ph_assert((SELECT count(*)=2 FROM notifications WHERE user_id=u AND reference_id=leader) AND (SELECT count(*)=2 FROM admin_audit_logs WHERE entity_id=leader::text),'retry silent, notes audited once');
 SELECT id INTO old_notice FROM notifications WHERE user_id=u AND reference_id=hof AND channel='push';
 PERFORM pg_temp.ph_assert(hg_prize_notice_valid(old_notice),'prepared notice initially valid');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',a)::text,true);PERFORM set_config('role','authenticated',true);
 UPDATE hall_of_fame_rewards SET status='fulfilled',fulfilled_by=a WHERE id=hof;
 UPDATE exclusive_spin_fulfillments SET status='fulfilled',fulfilled_by=a WHERE id=spin;
 PERFORM set_config('role','none',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM pg_temp.ph_assert(NOT hg_prize_notice_valid(old_notice),'old prepared push becomes stale');
 r:=hg_claim_notification_dispatch_v2(old_notice);
 PERFORM pg_temp.ph_assert(r->>'state'='claimed','queued handover is recoverable by worker');
 PERFORM pg_temp.ph_assert(NOT hg_begin_notification_dispatch(old_notice,(r->>'token')::uuid,'{}'),'send boundary refuses superseded status');
 PERFORM pg_temp.ph_assert((SELECT status='skipped' FROM notification_deliveries WHERE id=old_notice),'stale receipt not falsely sent');
 SELECT id INTO current_notice FROM notifications WHERE user_id=u AND reference_id=spin AND channel='push';
 PERFORM pg_temp.ph_assert(hg_prize_notice_valid(current_notice),'exclusive physical notice current');
 UPDATE exclusive_spin_fulfillments SET status='fulfilled' WHERE id=automatic;
 PERFORM pg_temp.ph_assert(NOT EXISTS(SELECT 1 FROM notifications WHERE reference_id=automatic),'automatic financial rewards untouched');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',b)::text,true);PERFORM set_config('role','authenticated',true);
 UPDATE hall_of_fame_rewards SET notes='forbidden' WHERE id=hof;GET DIAGNOSTICS n=ROW_COUNT;
 PERFORM set_config('role','none',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM pg_temp.ph_assert(n=0,'cross-campus admin cannot edit');
 PERFORM pg_temp.ph_assert(NOT has_function_privilege('authenticated','hg_internal.prize_handover_effects()','execute') AND NOT has_function_privilege('authenticated','public.hg_prize_notice_valid(uuid)','execute'),'private trigger and validator');
END$$;
ROLLBACK;
SELECT 'passed: three physical prize families, status/audit/inbox/outbox atomicity, repeat/notes timestamp conservation, terminal and campus guards, superseded-notice send check and automatic HP isolation; all fixtures rolled back' evidence;
